import json,pathlib,hashlib
R=pathlib.Path(__file__).resolve().parent
load=lambda n:json.load(open(R/n))
save=lambda n,v:(R/n).write_text(json.dumps(v,indent=2)+'\n')
source=load('source-analysis.json');short=load('shortcut-results.json')
ped={'learner_operation':source['skill']+' Scan the first nonzero entry of each nonzero row and take the complement of their column indices.',
'fixed_features':[{'feature':'Matrix already in row echelon form; small integer entries and observed shapes.','justification':'Tutorial Introduction defines pivots as first nonzero entries; source KP precedes the separate general-matrix elimination KP. Keep scanning workload comparable.'},{'feature':'One checkbox per column, complete true/false bank, one or two selected columns.','justification':'All 17 source questions use this contract. One or two non-pivots supports complement classification without expanding workload to zero matrices/full rank cases.'},{'feature':'Displayed columns are in natural numeric order.','justification':'Column numbering identifies matrix positions. Position is not held correct; every eligible non-pivot assignment for each shape/rank is covered.'}],
'answer_roles':[{'role':'Columns containing row-leading nonzero entries.','eligible_variation':'Move leading entries while preserving increasing pivot positions and zero rows last; choose eligible rank/shape.','observed':'58 explicit structures, all retained in the maximal generated batch; fresh samples and delivered batch cover different leading positions.'},{'role':'Columns selected as the complement.','eligible_variation':'Every eligible column index can be non-pivot; one and two selections, leading/interior/trailing and nonzero non-pivot vectors.','observed':'Five delivered batch subsets are {1,5}, {4,5}, {1}, {1,2}, {2}; full structural controls cover each eligible subset.'},{'role':'Matrix name and right-of-pivot coefficients.','eligible_variation':'Change A/B/P/R and signs/magnitudes without changing membership unless a first-nonzero position changes.','observed':'Conditional label/shape probes retained; controlled irrelevant coefficient edit preserves membership and grader outcomes.'}],
'coverage':[{'case':'All supplied source cases, including complete Boolean banks.','sample_refs':['source-replays.json','source-replay-results.json'],'result':'17/17 match source prompts, solutions and complete labelled banks after whitespace normalization.'},{'case':'Eligible shape/rank/pivot-position cases and coefficient boundaries.','sample_refs':['structural-samples.json','maximal-batch.json','resampling-results.json'],'result':'58 cases with entries at -9,0,9; all REF and correct complements; batch of 58 reaches all structures after 304 proposals.'},{'case':'Fresh generation and exact delivered runner batch.','sample_refs':['fresh-samples.json','runner-batch.json','delivery-fresh/accepted.json','delivery-batch/accepted.json','shortcut-results.json'],'result':'120/120 fresh and 5/5 exact batch records survive shared delivery; tested decision distributions unchanged. Batch has five distinct correct subsets.'}],
'counterfactuals':[{'kind':'relevant','change':'In the same 3x4 matrix change a22 from 3 to 0, shifting row 2 pivot from column 2 to 3.','expected':'Selected columns change from {3,4} to {2,4}. Prompt, vectors, explanation and native checkbox grading must follow.','observed':'Both matrices and explanations agree; native grader accepts new membership and rejects the old column-2/3 actions; actual UI screenshots show changed row 2 and selected fields.','status':'passed','justification':'First nonzero position determines pivot membership by the lesson definition.','sample_refs':['counterfactual-records.json','counterfactual-results.json','grader-results.json','render-pairs/rendering.json','render-pairs/question-001.png','render-pairs/question-002.png']},{'kind':'irrelevant','change':'Hold pivots fixed; change a12 from 4 to -9.','expected':'Selected columns stay {3,4}; prompt, vector and solution matrix reflect the changed coefficient.','observed':'Membership is unchanged; both native Boolean actions per field give the same acceptance pattern, and rendered changed vector/matrix retain the same selection and conclusion.','status':'passed','justification':'An entry to the right of an existing leading entry does not alter first-nonzero columns.','sample_refs':['counterfactual-records.json','counterfactual-results.json','grader-results.json','render-pairs/rendering.json','render-pairs/question-001.png','render-pairs/question-003.png']}],
'shortcut_probes':short['probes'],
'delivery':{'stages_examined':['generator explicit-parameter rejection','nonempty checkbox wrapper','internal structural rejection/resampling','requested easy difficulty','publisher normalization and inventory/within-batch deduplication','captured easy-only weighted learner selection and representative history exclusions'],'sample_refs':['rejection-results.json','resampling-results.json','delivery-fresh/delivery.json','delivery-batch/delivery.json','selection-results.json','shortcut-results.json'],'result':'Every tested structure is reachable. All 120 fresh and five runner records survive normalization and captured-inventory deduplication. Easy-positive within-band selection retains reachability under tested histories; unconfigured selection deterministically picks first eligible ID. No perfect repeated fixed-subset cue by label or shape was found. Zero-column simplification follows the taught definition and does not answer all batch records.'},
'limitations':['Finite tests do not prove absence of every shortcut. Small batch singleton cue groups cannot establish a systematic predictor.','Inventory and deduplication conclusions are based on captured basis 5362; concurrent inventory changes are outside this read-only review.','Active learner history/policy was not supplied; selection is a faithful conditional simulation with actual captured IDs, not a live session.','No diagrams or external assets occur. Free-entry equivalent-notation tests are inapplicable because every field is a Boolean checkbox; both real UI actions were tested.']}
save('pedagogical-variation.json',ped)
save('render-inspection.json',{'actual_renderer_reports':['render/rendering.json','render-pairs/rendering.json'],'screenshots_visually_inspected':['render/question-001.png','render/question-004.png','render-pairs/question-001.png','render-pairs/question-002.png','render-pairs/question-003.png'],'observations':['Math matrices and column vectors render with expected row/column counts and no exposed TeX.','Checkboxes visibly match selected and unselected membership; the 3x4 controlled pair changes selected columns 3->2 while column 4 stays checked.','Irrelevant a12 change is visible in prompt, vector and solution while checkboxes remain columns 3 and 4.','Worked solutions and matrix brackets are legible. Automatic reports have zero math/JS/image/glyph errors.','Ordinal suffix can wrap to next line at the preview width; meaning remains readable and no mathematical content is missing.'],'passed':True})
# Completion audit: require claims backed by actual results rather than normal process exits.
assert all(r['prompt'] and r['solution'] and r['complete_banks'] and not r['math']['errors'] for r in load('source-replay-results.json'))
assert all(not r['errors'] for rs in load('math-results.json').values() for r in rs)
assert all(r['rejected'] for r in load('rejection-results.json'))
assert all(not r['math']['errors'] for r in load('inventory-inspection.json')['questions'])
assert all(load('packaging-results.json')[k] for k in ['dependencies_exact','deterministic','relocation_equal','hashes_unchanged'])
assert load('grader-results.json')['accepted_checks']==356 and load('grader-results.json')['rejected_checks']==356
assert load('render/rendering.json')['passed'] and load('render-pairs/rendering.json')['passed']
assert load('delivery-batch/delivery.json')['accepted_count']==5 and load('delivery-fresh/delivery.json')['accepted_count']==120
assert load('resampling-results.json')['same_as_stream']
assert all(t['all_eligible_reached'] for t in load('selection-results.json')['trials'])
assert all(load('counterfactual-results.json')[k] for k in ['relevant_passed','irrelevant_passed'])
P=R.parent/'workspace';after={str(p.relative_to(P)):hashlib.sha256(p.read_bytes()).hexdigest() for p in P.rglob('*') if p.is_file()};assert after==load('package-hashes-before.json');save('package-hashes-after.json',after)
# Validate exact supplied pedagogical schema if the review environment has jsonschema.
try:
 import jsonschema
 jsonschema.validate(ped,json.load(open('/home/jake/Developer/Course_Academy/generate/pipeline/pedagogical-variation.schema.json')))
 schema='validated with jsonschema'
except ImportError:
 schema='jsonschema unavailable; required fields, values, and local evidence references checked below'
for p in ped['shortcut_probes']:
 assert p['total']>=p['correct']>=0 and 0<=p['baseline']<=1
for entry in ped['coverage']+ped['counterfactuals']+ped['shortcut_probes']+[ped['delivery']]:
 for ref in entry['sample_refs']:assert not pathlib.Path(ref).is_absolute() and (R/ref).is_file() and (R/ref).stat().st_size>0
save('evidence-contract-results.json',{'pedagogical_schema':schema,'all_sample_refs_local_nonempty':True,'package_unchanged':True,'all_completion_assertions':True})
print(json.dumps({'schema':schema,'package_unchanged':True,'completion_assertions':True}))
